import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.nativerdf.ValueStore;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class GH6400BootstrapDurabilityReviewTest {

	@TempDir
	Path directory;

	@Test
	void synchronousBootstrapForcesWalUnderIntervalPolicy() throws Exception {
		Path dataDirectory = Files.createDirectories(directory.resolve("data"));
		try (ValueStore original = new ValueStore(dataDirectory.toFile())) {
			original.storeValue(SimpleValueFactory.getInstance().createLiteral("bootstrap must reach stable storage"));
			original.sync();
		}
		Path walDirectory = directory.resolve("wal");
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(walDirectory)
				.storeUuid("bootstrap-durability-review")
				.syncPolicy(ValueStoreWalConfig.SyncPolicy.INTERVAL)
				.syncBootstrapOnOpen(true)
				.build();
		AtomicInteger forces = new AtomicInteger();
		ValueStoreWalDebug.setForceListener(path -> {
			if (path.getParent().equals(walDirectory)) {
				forces.incrementAndGet();
			}
		});
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore rebuilt = new ValueStore(dataDirectory.toFile(), false, 8, 8, 8, 8, wal)) {
			assertThat(forces.get()).as("successful bootstrap must force the WAL even under INTERVAL policy")
					.isGreaterThan(0);
		} finally {
			ValueStoreWalDebug.clearForceListener();
		}
	}

	@Test
	void bootstrapBarrierForcesAnAlreadyFlushedIntervalRecord() throws Exception {
		ValueStoreWalConfig config = writerConfig();
		AtomicInteger forces = new AtomicInteger();
		ValueStoreWalDebug.setForceListener(path -> forces.incrementAndGet());
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			long lsn = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "already flushed", "", "", 0);
			wal.awaitDurable(lsn);
			awaitVisibleRecord(config);
			assertThat(forces.get()).as("ordinary INTERVAL writes must retain their existing policy").isZero();

			wal.awaitBootstrapDurable(lsn);

			assertThat(forces.get()).as("a flush acknowledgment cannot satisfy bootstrap durability")
					.isGreaterThan(0);
		} finally {
			ValueStoreWalDebug.clearForceListener();
		}
	}

	@Test
	void bootstrapBarrierRejectsClosedWal() throws Exception {
		ValueStoreWAL wal = ValueStoreWAL.open(writerConfig());
		long lsn;
		try (wal) {
			lsn = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "closed before force", "", "", 0);
		}

		assertThatThrownBy(() -> wal.awaitBootstrapDurable(lsn)).isInstanceOf(IOException.class);
	}

	@Test
	void closeReleasesBootstrapWaiterBeforeWriterCanForce() throws Exception {
		CountDownLatch writerEntered = new CountDownLatch(1);
		CountDownLatch releaseWriter = new CountDownLatch(1);
		ValueStoreWAL.setChannelOpenerForTesting((path, options) -> {
			writerEntered.countDown();
			try {
				if (!releaseWriter.await(30, TimeUnit.SECONDS)) {
					throw new IOException("Test did not release WAL writer");
				}
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new IOException(e);
			}
			return FileChannel.open(path, options);
		});
		try (var executor = Executors.newFixedThreadPool(2);
				ValueStoreWAL wal = ValueStoreWAL.open(writerConfig())) {
			try {
				long lsn = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "waiting for force", "", "", 0);
				assertThat(writerEntered.await(10, TimeUnit.SECONDS)).isTrue();
				CountDownLatch waiterEntered = new CountDownLatch(1);
				var waiting = executor.submit(() -> {
					waiterEntered.countDown();
					wal.awaitBootstrapDurable(lsn);
					return null;
				});
				assertThat(waiterEntered.await(10, TimeUnit.SECONDS)).isTrue();
				var closing = executor.submit(() -> {
					wal.close();
					return null;
				});

				assertThatThrownBy(() -> waiting.get(10, TimeUnit.SECONDS))
						.isInstanceOf(ExecutionException.class)
						.hasCauseInstanceOf(IOException.class);
				releaseWriter.countDown();
				closing.get(10, TimeUnit.SECONDS);
			} finally {
				releaseWriter.countDown();
			}
		} finally {
			releaseWriter.countDown();
			ValueStoreWAL.resetChannelOpenerForTesting();
		}
	}

	@Test
	void writerFailureCannotAcknowledgeBootstrapDurability() throws Exception {
		ValueStoreWalDebug.setForceListener(path -> {
			throw new IllegalStateException("injected bootstrap force failure");
		});
		ValueStoreWAL wal = ValueStoreWAL.open(writerConfig());
		try {
			long lsn = wal.logMint(1, ValueStoreWalValueKind.LITERAL, "force failure", "", "", 0);
			assertThatThrownBy(() -> wal.awaitBootstrapDurable(lsn)).isInstanceOf(IOException.class)
					.hasRootCauseMessage("injected bootstrap force failure");
		} finally {
			try {
				assertThatThrownBy(wal::close).isInstanceOf(IOException.class);
			} finally {
				ValueStoreWalDebug.clearForceListener();
			}
		}
	}

	private ValueStoreWalConfig writerConfig() {
		return ValueStoreWalConfig.builder()
				.walDirectory(directory.resolve("writer-wal"))
				.storeUuid("strict-bootstrap-barrier")
				.syncPolicy(ValueStoreWalConfig.SyncPolicy.INTERVAL)
				.syncInterval(Duration.ZERO)
				.idlePollInterval(Duration.ofMillis(1))
				.build();
	}

	private static void awaitVisibleRecord(ValueStoreWalConfig config) throws Exception {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (System.nanoTime() < deadline) {
			try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
				if (!reader.scan().records().isEmpty()) {
					return;
				}
			}
			Thread.yield();
		}
		throw new AssertionError("INTERVAL writer did not flush its record");
	}
}
